 checks=failed=0;CHECK(bh_math_environment_enter(&env),"PC53");CHECK(bh_config_init(&config,0)&&bh_config_load(&config,"mission-story-fixture.cfg"),"actual config bootstrap");CHECK(bh_entities_init(&pool,32,0)&&bh_sound_queue_init(&sounds,0,0,0),"real pool/sound owners");memset(&life,0,sizeof(life));life.timers.pool=&pool;life.sounds=&sounds;a=bh_sound_resource_allocate(&sounds);b=bh_sound_resource_allocate(&sounds);pickup=bh_sound_resource_allocate(&sounds);CHECK(a&&b&&pickup,"actual cue resources");a->streaming=b->streaming=pickup->streaming=1;a->base_frequency=b->base_frequency=pickup->base_frequency=8000;player=bh_entity_acquire(&pool);actor=bh_entity_acquire(&pool);head=actor;CHECK(player&&actor,"real player and actor allocations");memset(&progress,0,sizeof(progress));progress.config=&config;progress.path="mission-story-fixture.cfg";progress.lifetime=&life;progress.first_sound=a->index;progress.unlocked_sound=b->index;CHECK(bh_weapon_factory_open(&factory,&pool,&sounds),"real factory binding");for(i=0;i<10;++i){weapons[i]=bh_weapon_factory_create(&factory,i);CHECK(weapons[i]!=0,"actual weapon object");field(player,0x258+4*i,(unsigned long)weapons[i]);}
 memset(&c,0,sizeof(c));c.progress=&progress;c.messages=&messages;c.player=player;c.weapons=&factory.registry;c.actors=&head;c.actor_limit=32;c.availability=availability;c.sound=&sounds;c.pickup_sound=pickup->index;c.camera=(BHCameraState*)((char*)player+0xe8);c.force_control=&force;c.force_gate=&force_gate;c.ending=&ending;memset(availability,0,sizeof(availability));CHECK(bh_camera_state_init(c.camera,0),"actual embedded camera");CHECK(bh_mission_story_bind(&c,actor),"real installed story query");field(actor,0xfc,1);field(actor,0xf0,0);
 for(i=0;i<sizeof(expected_messages)/sizeof(expected_messages[0]);++i){bh_message_state_init(&messages);messages.panel_entity=player;messages.panel_step_identity=&identity;packet[2]=expected_messages[i].id;queued=c.queued;CHECK(bh_mission_story_dispatch(&c,packet)&&c.queued==queued+1&&messages.ring_count==1,"all95 original message cases and real side-effect closures");CHECK(hash(messages.ring[messages.last_index])==expected_messages[i].hash,"exact immutable-reference text fingerprint");free_cues(&pool);}
 CHECK(c.force_control&&force==bh_player_force_control_a&&force_gate==0&&c.camera->current.mode==8,"finale installs real force owner and camera8");CHECK(ending==1&&c.broadcasts==6,"finale and clear/broadcast branches");bh_message_state_init(&messages);messages.panel_entity=player;messages.panel_step_identity=&identity;packet[2]=0x960;CHECK(bh_mission_story_dispatch(&c,packet)&&ending==2&&!messages.ring_count,"ending2 has no message");packet[2]=0x7de;queued=c.queued;used=pool.used;CHECK(bh_mission_story_dispatch(&c,packet)&&c.queued==queued&&pool.used==used,"unknown message no-op");packet[0]=15;packet[2]=3001;CHECK(bh_mission_story_dispatch(&c,packet)&&!availability[0][31],"event gate");packet[0]=14;
 for(i=3001;i<=3005;++i){packet[2]=(long)i;CHECK(bh_mission_story_dispatch(&c,packet),"all availability events");CHECK(bh_mission_story_dispatch(&c,packet),"repeated event idempotent");}CHECK(availability[0][31]==6&&availability[1][31]==6&&availability[2][31]==6&&availability[3][31]==4,"four independent original row counts");CHECK(availability[0][0]&&availability[0][10]&&availability[0][6]&&availability[1][3]&&availability[1][7]&&availability[2][6]&&availability[3][5]&&availability[3][7]&&availability[3][8]&&availability[3][12]&&!availability[3][0],"original availability indices");availability[0][31]=0xffffffffUL;availability[0][6]=0;packet[2]=3005;CHECK(bh_mission_story_dispatch(&c,packet)&&!availability[0][31],"original wrapped count");
 for(i=0;i<10;++i){state=bh_weapon_object_state(weapons[i]);state->common.ammo=123;state->common.ammo_limit=i==7?-8:i==9?(-2147483647L-1):55;}srand(71);rng=rand();srand(71);packet[2]=3006;CHECK(bh_mission_story_dispatch(&c,packet)&&rand()==rng&&pickup->stream_head!=0,"actual refill cue, no invented RNG");for(i=0;i<10;++i){state=bh_weapon_object_state(weapons[i]);CHECK(state->common.ammo==(i<5?123:i==7?-8:i==9?(-2147483647L-1):0),"five refill slots and signed ceilings");}
 setprogress(&config,-1);packet[2]=3000;attempts=progress.save_attempts;CHECK(bh_mission_story_dispatch(&c,packet)&&progression(&config)==0&&progress.save_attempts==attempts+1,"non-message completion clamps and saves");at=pool.active;CHECK(at->step==bh_mission_sound_tick&&bh_script_lifetime_read(at,&cue_state)&&cue_state.mission_resource==a->index&&cue_state.mission_countdown==4,"actual deferred first cue");for(j=0;j<122&&at->step==bh_mission_sound_tick;++j){if(pool.active!=at)break;at->step(at);}CHECK(a->stream_head!=0,"actual cue expiry requests source sound");free_cues(&pool);
 setprogress(&config,8);attempts=progress.save_attempts;bh_message_state_init(&messages);messages.panel_entity=player;messages.panel_step_identity=&identity;packet[2]=0x7e5;CHECK(bh_mission_story_dispatch(&c,packet)&&progression(&config)==8&&progress.save_attempts==attempts,"unlock cue does not lower progression or rewrite save");CHECK(bh_script_lifetime_read(pool.active,&cue_state)&&cue_state.mission_resource==b->index,"actual unlock cue owner");free_cues(&pool);CHECK(bh_config_init(&loaded,0)&&bh_config_load(&loaded,progress.path)&&progression(&loaded)==0,"real persisted earlier progression");bh_config_dispose(&loaded);
